1	import { daysBetween } from './dates.js';
2	import { balanceDue } from './payments.js';
3	import { roundCents } from './money.js';
4	
5	/**
6	 * Generate a report of overdue invoices.
7	 * @param {Array} invoices - All invoices to check
8	 * @param {string} asOf - Date in YYYY-MM-DD format; invoices with dueDate < asOf are overdue
9	 * @returns {Array} Array of { number, customerId, dueDate, daysOverdue, due }, sorted by daysOverdue descending
10	 */
11	export function overdueInvoices(invoices, asOf) {
12	  // Filter for overdue invoices (issued or partially_paid, with dueDate before asOf)
13	  const overdue = (invoices || []).filter((inv) =>
14	    (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf
15	  );
16	
17	  // Map to report format
18	  const result = overdue
19	    .map((inv) => {
20	      const dueResult = balanceDue(inv);
21	      const due = dueResult.ok ? dueResult.value : 0;
22	      const daysOverdue = daysBetween(inv.dueDate, asOf);
23	
24	      return {
25	        number: inv.number,
26	        customerId: inv.customerId,
27	        dueDate: inv.dueDate,
28	        daysOverdue,
29	        due,
30	      };
31	    })
32	    .sort((a, b) => b.daysOverdue - a.daysOverdue);
33	
34	  return result;
35	}
36	
37	/**
38	 * Generate a VAT summary by rate for issued/partially_paid/paid invoices.
39	 * @param {Array} invoices - All invoices to summarize
40	 * @returns {Array} Array of { rate, base, vat }, sorted by rate descending
41	 */
42	export function vatSummary(invoices) {
43	  const vatMap = {}; // rate -> { base, vat }
44	
45	  (invoices || []).forEach((inv) => {
46	    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) return;
47	
48	    inv.lines?.forEach((line) => {
49	      const rate = line.vatRate;
50	      const lineTotal = line.qty * line.unitPrice;
51	      const discount = roundCents(lineTotal * (line.discountPercent || 0) / 100);
52	      const base = lineTotal - discount;
53	      const vatAmount = roundCents(base * rate / 100);
54	
55	      if (!vatMap[rate]) {
56	        vatMap[rate] = { base: 0, vat: 0 };
57	      }
