  // Due date is 2026-10-21, asOf is 2026-10-22 (1 day overdue)
  // Balance due: 10285, fee = 10285 * 1 * 0.0004 = 4.114 -> 4 cents
  const r = lateFee(issued.value, '2026-10-22');
  assert.equal(r, 4);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);

  // Due date is 2026-10-21, asOf is 2026-10-31 (10 days overdue)
  // Balance due: 10285, fee = 10285 * 10 * 0.0004 = 41.14 -> 41 cents
  const r = lateFee(issued.value, '2026-10-31');
  assert.equal(r, 41);
});

test('lateFee with partially paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-10' });

  // Due date is 2026-10-21, asOf is 2026-10-22 (1 day overdue)
  // Balance due: 51425 - 5000 = 46425
  // fee = 46425 * 1 * 0.0004 = 18.57 -> 19 cents (rounded)
  const r = lateFee(partial.value, '2026-10-22');
  assert.equal(r, 19);
});

test('lateFee returns 0 for paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const paid = recordPayment(issued.value, { amount: 10285, date: '2026-10-10' });

  // Even if we check after due date, paid invoice has 0 balance
  const r = lateFee(paid.value, '2026-10-30');
  assert.equal(r, 0);
});

test('lateFee returns 0 for draft invoice with no due date', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });

  // Draft has default NET30 terms, so it has a dueDate
  // But it's in draft status, so balanceDue should handle it
  // dueDate is 2026-11-06, asOf is 2026-10-22 (not yet due)
  const r = lateFee(draft.value, '2026-10-22');
  assert.equal(r, 0);
});

test('lateFee with different due dates and same overdue days', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }], // 10285
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }], // 20570
    terms: 'NET14',
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  // invoice1: due 2026-10-15, asOf 2026-10-22 (7 days overdue)
  // fee = 10285 * 7 * 0.0004 = 28.798 -> 29 cents
  const r1 = lateFee(issued1.value, '2026-10-22');
  assert.equal(r1, 29);

  // invoice2: due 2026-10-21, asOf 2026-10-22 (1 day overdue)
  // fee = 20570 * 1 * 0.0004 = 8.228 -> 8 cents
  const r2 = lateFee(issued2.value, '2026-10-22');
  assert.equal(r2, 8);
});

test('lateFee with large balance and many days', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }], // 120000, 25200 VAT = 145200
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);

  // Due date is 2026-01-15, asOf is 2026-03-31 (75 days overdue)
  // fee = 145200 * 75 * 0.0004 = 4356 cents
  const r = lateFee(issued.value, '2026-03-31');
  assert.equal(r, 4356);
});

test('lateFee returns integer cents', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 1, discountPercent: 0 }], // 37, 3 VAT = 40
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);

  // Due date is 2026-10-21, asOf is 2026-10-25 (4 days overdue)
  // fee = 40 * 4 * 0.0004 = 0.0064 -> 0 cents (rounds to 0)
  const r = lateFee(issued.value, '2026-10-25');
  assert.equal(typeof r, 'number');
  assert.equal(r, Number.isInteger(r) ? r : Math.round(r));
});

test('lateFee with 0 balance due (fully paid)', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const paid = recordPayment(issued.value, { amount: 10285, date: '2026-10-08' });

  // Invoice is fully paid, no balance, no fee
  const r = lateFee(paid.value, '2026-10-30');
  assert.equal(r, 0);
});

