  assert.equal(r.ok, true);
  // Line 1: 85000, base 10% = 8500, bulk 2.5% on 76500 = 1912, total = 10412
  // Line 2: 95000, base 20% = 19000, bulk 2.5% on 76000 = 1900, total = 20900
  // Total discount: 31312, Total VAT: 31224
  assert.equal(r.value.subtotal, 180000);
  assert.equal(r.value.discount, 31312);
  assert.equal(r.value.vat, 31224);
  assert.equal(r.value.total, 180000 - 31312 + 31224);

