    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET60',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

