    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  // C-001 is gold tier = 5% discount
  assert.equal(r.value.lines[1].discountPercent, 5);
});

test('addLine explicit discountPercent 0 overrides tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const r = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 0);
});

test('tier discount affects invoice totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 100 * 8500 = 850000, C-001 gold tier = 5% = 42500
  // After base discount: 807500, bulk discount 2.5% = 20187.5 -> 20188
  // Total discount: 42500 + 20188 = 62688
  // VAT on (850000 - 62688) = 787312 at 21% = 165336.52 -> 165337
  assert.equal(r.value.subtotal, 850000);
  assert.equal(r.value.discount, 62688);
  assert.equal(r.value.vat, 165337);
  assert.equal(r.value.total, 850000 - 62688 + 165337);
});

test('invoiceTotals calculates VAT per line after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 100 * 8500 = 850000, base discount 10% = 85000
  // After base: 765000, bulk discount 2.5% = 19125
  // Total discount: 85000 + 19125 = 104125
  // VAT on (850000 - 104125) = 745875 at 21% = 156632.5 -> 156633
  assert.equal(r.value.subtotal, 850000);
  assert.equal(r.value.discount, 104125);
  assert.equal(r.value.vat, 156633);
  assert.equal(r.value.total, 850000 - 104125 + 156633);
});

test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 100, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // DES-HOUR: 850000, bulk 21250, after 828750, VAT 21% = 174037.5 -> 174038
  // PRINT-A4: 3700, bulk 92.5 -> 92, after 3608, VAT 9% = 324.72 -> 325
  // Total discount: 21250 + 92 = 21342, Total VAT = 174038 + 325 = 174363
  assert.equal(r.value.subtotal, 853700);
  assert.equal(r.value.discount, 21342);
  assert.equal(r.value.vat, 174363);
  assert.equal(r.value.total, 853700 - 21342 + 174363);
});

test('invoiceTotals handles zero VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // WORKSHOP-DAY is 60000 cents, VAT exempt (0%)
  assert.equal(r.value.subtotal, 60000);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 60000);
});

test('invoiceTotals rounds VAT per line, not on invoice total', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21, discountPercent: 0 },
      { qty: 3, unitPrice: 100, vatRate: 21, discountPercent: 0 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 300, VAT 21% = 63
  // Line 2: 300, VAT 21% = 63
  // Total VAT = 126 (not calculated as 600 * 0.21 = 126)
  assert.equal(r.value.vat, 126);
});

