test('invoiceTotals includes voucher in calculation', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const withVoucher = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 5000 });
  assert.equal(withVoucher.ok, true);

  const r = invoiceTotals(withVoucher.value);
  assert.equal(r.ok, true);
  // Subtotal: 42500, VAT 21%: 8925, Voucher: 5000
  // Total: 42500 + 8925 - 5000 = 46425
  assert.equal(r.value.subtotal, 42500);
  assert.equal(r.value.vat, 8925);
  assert.equal(r.value.voucher, 5000);
  assert.equal(r.value.total, 46425);
});

test('invoiceTotals clamps total at 0 when voucher exceeds amount', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 1, unitPrice: 100, vatRate: 0, discountPercent: 0 }],
    voucher: { code: 'MEGA100', amount: 5000 },
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Subtotal: 100, VAT: 0, Voucher: 5000
  // Total would be: 100 + 0 - 5000 = -4900, but clamped to 0
  assert.equal(r.value.total, 0);
  assert.equal(r.value.voucher, 5000);
});

